	if err := fs.Parse(args); err != nil {
		return err
	}
	input, err := readStdinWithTimeout(stdin, 100*time.Millisecond)
	if err != nil {
		return err
	}
	event, err := parser.ParseHook(*hook, input)
	if err != nil {
		return err
	}
	if event == nil {
		_, err = io.WriteString(stdout, "null\n")
		return err
	}
	return WriteJSON(stdout, event)
}

