// Package pi implements the Agent interface for the Pi coding agent.
package pi

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNamePi, NewPiAgent)
}

// PiAgent implements the Agent interface for the Pi coding agent.
//
//nolint:revive // PiAgent is clearer than Agent in this context
type PiAgent struct{}

// NewPiAgent creates a new Pi agent instance.
func NewPiAgent() agent.Agent {
	return &PiAgent{}
}

// Name returns the agent registry key.
func (p *PiAgent) Name() types.AgentName {
	return agent.AgentNamePi
}

// Type returns the agent type identifier.
func (p *PiAgent) Type() types.AgentType {
	return agent.AgentTypePi
}

// Description returns a human-readable description.
func (p *PiAgent) Description() string {
	return "Pi - The Pi coding agent"
}

// IsPreview returns true because this is a new integration.
func (p *PiAgent) IsPreview() bool { return true }

// DetectPresence checks whether the Pi binary is on PATH.
func (p *PiAgent) DetectPresence(_ context.Context) (bool, error) {
	_, err := exec.LookPath("pi")
	return err == nil, nil
}

// ProtectedDirs returns directories that Pi uses for config/state.
func (p *PiAgent) ProtectedDirs() []string { return []string{".pi"} }

// GetSessionID extracts the session ID from hook input.
func (p *PiAgent) GetSessionID(input *agent.HookInput) string {
	if input != nil && input.SessionID != "" {
		return input.SessionID
	}
	return ""
}

// GetSessionDir returns the directory where Entire caches Pi session data.
// Pi stores native sessions under ~/.pi/agent/sessions, but Entire keeps a
// per-repo cache at .entire/tmp so attach/rewind has a stable location.
func (p *PiAgent) GetSessionDir(repoPath string) (string, error) {
	return filepath.Join(repoPath, ".entire", "tmp"), nil
}

// ResolveSessionFile returns the cached transcript path for a session ID.
func (p *PiAgent) ResolveSessionFile(sessionDir, sessionID string) string {
	return filepath.Join(sessionDir, sessionID+".json")
}

// ReadSession reads a session from Pi's storage (JSONL session file).
func (p *PiAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input == nil || input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}

	data, err := os.ReadFile(input.SessionRef) //nolint:gosec // path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("read session file: %w", err)
	}

	sessionID := input.SessionID
	if sessionID == "" {
		sessionID = extractSessionIDFromPath(input.SessionRef)
	}

	startTime, _ := parseSessionStartTime(data)

	return &agent.AgentSession{
		SessionID:  sessionID,
		AgentName:  p.Name(),
		SessionRef: input.SessionRef,
		StartTime:  startTime,
		NativeData: data,
	}, nil
}

// WriteSession writes a session to Pi's storage.
func (p *PiAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}
	if session.AgentName != "" && session.AgentName != p.Name() {
		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, p.Name())
	}
	if session.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}
	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o700); err != nil {
		return fmt.Errorf("create session dir: %w", err)
	}
	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("write session file: %w", err)
	}
	return nil
}

// FormatResumeCommand returns the command to resume a Pi session.
func (p *PiAgent) FormatResumeCommand(_ string) string {
	return "pi --continue"
}

// ReadTranscript reads the raw JSONL transcript bytes for a session.
func (p *PiAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("read transcript: %w", err)
	}
	return data, nil
}

// ChunkTranscript splits a JSONL transcript at line boundaries.
func (p *PiAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	chunks, err := agent.ChunkJSONL(content, maxSize)
	if err != nil {
		return nil, fmt.Errorf("chunk JSONL transcript: %w", err)
	}
	return chunks, nil
}

// ReassembleTranscript concatenates JSONL chunks with newlines.
func (p *PiAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}

package pi

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Pi JSONL entry types.
const (
	entryTypeMessage = "message"
	contentTypeText  = "text"
)

// maxScannerLine is 1 MB — large enough for Pi JSONL lines that may
// contain thinking blocks or full file contents in tool call arguments.
const maxScannerLine = 1 << 20

func newJSONLScanner(data []byte) *bufio.Scanner {
	s := bufio.NewScanner(bytes.NewReader(data))
	s.Buffer(make([]byte, 0, maxScannerLine), maxScannerLine)
	return s
}

// countLines returns the number of non-empty lines in data.
func countLines(data []byte) int {
	if len(data) == 0 {
		return 0
	}
	n := bytes.Count(data, []byte{'\n'})
	if data[len(data)-1] != '\n' {
		n++
	}
	return n
}

// skipLines returns data with the first n lines removed.
func skipLines(data []byte, n int) []byte {
	if n <= 0 {
		return data
	}
	off := 0
	for i := 0; i < n && off < len(data); i++ {
		idx := bytes.IndexByte(data[off:], '\n')
		if idx < 0 {
			return nil
		}
		off += idx + 1
	}
	return data[off:]
}

type sessionEntry struct {
	Type      string `json:"type"`
	Version   int    `json:"version"`
	ID        string `json:"id"`
	Timestamp string `json:"timestamp"`
	Cwd       string `json:"cwd"`
}

type messageEntry struct {
	Type      string  `json:"type"`
	ID        string  `json:"id"`
	Timestamp string  `json:"timestamp"`
	Message   message `json:"message"`
}

type message struct {
	Role       string          `json:"role"`
	Content    json.RawMessage `json:"content"`
	Timestamp  json.Number     `json:"timestamp"`
	Usage      *tokenUsage     `json:"usage,omitempty"`
	StopReason string          `json:"stopReason,omitempty"`
	ToolCallID string          `json:"toolCallId,omitempty"`
	ToolName   string          `json:"toolName,omitempty"`
	IsError    bool            `json:"isError,omitempty"`
}

type tokenUsage struct {
	Input      int `json:"input"`
	Output     int `json:"output"`
	CacheRead  int `json:"cacheRead"`
	CacheWrite int `json:"cacheWrite"`
}

type contentItem struct {
	Type      string          `json:"type"`
	Text      string          `json:"text,omitempty"`
	Name      string          `json:"name,omitempty"`
	ID        string          `json:"id,omitempty"`
	Arguments json.RawMessage `json:"arguments,omitempty"`
}

// resolveActiveBranch returns the set of entry IDs on the active conversation
// branch. Pi transcripts form a tree (entries have id and parentId); the
// active branch is the path from the root to the last message entry.
// Returns nil if the transcript has no tree structure.
func resolveActiveBranch(data []byte) map[string]bool {
	type node struct {
		Type     string  `json:"type"`
		ID       string  `json:"id"`
		ParentID *string `json:"parentId"`
	}

	var lastMessageID string
	hasTree := false
	parentOf := make(map[string]string)

	scanner := newJSONLScanner(data)
	for scanner.Scan() {
		var n node
		if err := json.Unmarshal(scanner.Bytes(), &n); err != nil || n.ID == "" {
			continue
		}
		if n.ParentID != nil {
			parentOf[n.ID] = *n.ParentID
			if *n.ParentID != "" {
				hasTree = true
			}
		}
		if n.Type == entryTypeMessage {
			lastMessageID = n.ID
		}
	}

	if !hasTree || lastMessageID == "" {
		return nil
	}

	active := make(map[string]bool)
	for cur := lastMessageID; cur != ""; {
		if active[cur] {
			break
		}
		active[cur] = true
		parent, ok := parentOf[cur]
		if !ok {
			break
		}
		cur = parent
	}

	return active
}

// parseSessionStartTime extracts the session header timestamp from JSONL data.
func parseSessionStartTime(data []byte) (time.Time, error) {
	scanner := newJSONLScanner(data)
	for scanner.Scan() {
		var entry sessionEntry
		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
			continue
		}
		if entry.Type == "session" && entry.Timestamp != "" {
			t, err := time.Parse(time.RFC3339, entry.Timestamp)
			if err != nil {
				return time.Time{}, fmt.Errorf("parse session timestamp: %w", err)
			}
			return t, nil
		}
	}
	return time.Time{}, nil
}

// extractSessionIDFromPath extracts the UUID from a Pi session filename.
// Pattern: <timestamp>_<uuid>.jsonl → returns <uuid>
func extractSessionIDFromPath(path string) string {
	if path == "" {
		return ""
	}
	base := filepath.Base(path)
	if len(base) > 6 && base[len(base)-6:] == ".jsonl" {
		base = base[:len(base)-6]
	}
	for i := len(base) - 1; i >= 0; i-- {
		if base[i] == '_' {
			return base[i+1:]
		}
	}
	return base
}

// GetTranscriptPosition returns the number of lines in the JSONL transcript.
// The CLI uses this value as the offset for ExtractModifiedFilesFromOffset.
func (p *PiAgent) GetTranscriptPosition(path string) (int, error) {
	data, err := os.ReadFile(path) //nolint:gosec // path comes from agent hook input
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, err
	}
	return countLines(data), nil
}

// ExtractModifiedFilesFromOffset extracts files modified since the given line offset.
func (p *PiAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
	data, err := os.ReadFile(path) //nolint:gosec // path comes from agent hook input
	if err != nil {
		return nil, 0, err
	}

	totalLines := countLines(data)
	active := resolveActiveBranch(data)
	content := skipLines(data, startOffset)

	seen := make(map[string]bool)
	var files []string

	scanner := newJSONLScanner(content)
	for scanner.Scan() {
		var entry messageEntry
		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
			continue
		}
		if entry.Type != entryTypeMessage {
			continue
		}
		if active != nil && !active[entry.ID] {
			continue
		}
		if entry.Message.Role != "assistant" {
			continue
		}

		var items []contentItem
		if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
			continue
		}

		for _, item := range items {
			if item.Type != "toolCall" {
				continue
			}
			if item.Name != "write" && item.Name != "edit" {
				continue
			}
			var args struct {
				Path string `json:"path"`
			}
			if err := json.Unmarshal(item.Arguments, &args); err != nil {
				continue
			}
			if args.Path != "" && !seen[args.Path] {
				seen[args.Path] = true
				files = append(files, args.Path)
			}
		}
	}

	return files, totalLines, nil
}

// ExtractPrompts returns user prompts from the transcript starting at the given line offset.
func (p *PiAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // path comes from agent hook input
	if err != nil {
		return nil, err
	}

	active := resolveActiveBranch(data)
	content := skipLines(data, fromOffset)

	var prompts []string
	scanner := newJSONLScanner(content)
	for scanner.Scan() {
		var entry messageEntry
		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
			continue
		}
		if entry.Type != entryTypeMessage || entry.Message.Role != "user" {
			continue
		}
		if active != nil && !active[entry.ID] {
			continue
		}

		var items []contentItem
		if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
			continue
		}

		for _, item := range items {
			if item.Type == contentTypeText && item.Text != "" {
				prompts = append(prompts, item.Text)
			}
		}
	}

	return prompts, nil
}

// ExtractSummary returns the last assistant text response, or "" if none.
func (p *PiAgent) ExtractSummary(sessionRef string) (string, bool, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // path comes from agent hook input
	if err != nil {
		return "", false, err
	}

	active := resolveActiveBranch(data)

	var lastAssistantText string
	scanner := newJSONLScanner(data)
	for scanner.Scan() {
		var entry messageEntry
		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
			continue
		}
		if entry.Type != entryTypeMessage || entry.Message.Role != "assistant" {
			continue
		}
		if active != nil && !active[entry.ID] {
			continue
		}

		var items []contentItem
		if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
			continue
		}

		for _, item := range items {
			if item.Type == contentTypeText && item.Text != "" {
				lastAssistantText = item.Text
			}
		}
	}

	if lastAssistantText != "" {
		return lastAssistantText, true, nil
	}
	return "", false, nil
}

// CalculateTokenUsage sums token usage from assistant messages in the transcript
// starting at the given line offset.
func (p *PiAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
	active := resolveActiveBranch(transcriptData)
	content := skipLines(transcriptData, fromOffset)

	usage := &agent.TokenUsage{}
	scanner := newJSONLScanner(content)
	for scanner.Scan() {
		var entry messageEntry
		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
			continue
		}
		if entry.Type != entryTypeMessage || entry.Message.Role != "assistant" || entry.Message.Usage == nil {
			continue
		}
		if active != nil && !active[entry.ID] {
			continue
		}

		usage.InputTokens += entry.Message.Usage.Input
		usage.OutputTokens += entry.Message.Usage.Output
		usage.CacheReadTokens += entry.Message.Usage.CacheRead
		usage.CacheCreationTokens += entry.Message.Usage.CacheWrite
		usage.APICallCount++
	}

	return usage, nil
}

package pi

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

const (
	extensionDir      = ".pi/extensions/entire"
	extensionFile     = ".pi/extensions/entire/index.ts"
	activeSessionFile = "pi-active-session"
)

// Pi hook names — these become subcommands under `entire hooks pi`.
// Names match Pi's native event names (snake_case) so the TypeScript
// extension can pass them through verbatim.
const (
	HookNameSessionStart      = "session_start"
	HookNameBeforeAgentStart  = "before_agent_start"
	HookNameAgentEnd          = "agent_end"
	HookNameSessionShutdown   = "session_shutdown"
)

// piHookPayload is the JSON the TypeScript extension sends to
// `entire hooks pi <event>`.
type piHookPayload struct {
	Type         string `json:"type"`
	Cwd          string `json:"cwd,omitempty"`
	SessionFile  string `json:"session_file,omitempty"`
	SessionID    string `json:"session_id,omitempty"`
	Prompt       string `json:"prompt,omitempty"`
	MessageCount int    `json:"message_count,omitempty"`
	TurnIndex    int    `json:"turn_index,omitempty"`
}

// HookNames returns the hook verbs Pi supports.
func (p *PiAgent) HookNames() []string {
	return []string{
		HookNameSessionStart,
		HookNameBeforeAgentStart,
		HookNameAgentEnd,
		HookNameSessionShutdown,
	}
}

// ParseHookEvent translates a Pi hook into a normalized lifecycle Event.
// Returns nil if the hook has no lifecycle significance.
func (p *PiAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	const maxHookBytes = 10 * 1024 * 1024
	data, err := io.ReadAll(io.LimitReader(stdin, maxHookBytes))
	if err != nil {
		return nil, fmt.Errorf("read hook input: %w", err)
	}
	if len(data) == 0 {
		return nil, nil //nolint:nilnil // empty input → no event
	}

	var payload piHookPayload
	if err := json.Unmarshal(data, &payload); err != nil {
		return nil, fmt.Errorf("parse hook payload: %w", err)
	}

	sessionID := payload.SessionID
	if sessionID == "" {
		sessionID = extractSessionIDFromPath(payload.SessionFile)
	}

	repoRoot := repoRootForCtx(ctx)
	now := time.Now().UTC()

	switch hookName {
	case HookNameSessionStart:
		cacheSessionID(repoRoot, sessionID)
		return &agent.Event{
			Type:      agent.SessionStart,
			SessionID: sessionID,
			Timestamp: now,
		}, nil

	case HookNameBeforeAgentStart:
		if sessionID == "" {
			sessionID = readCachedSessionID(repoRoot)
		} else {
			cacheSessionID(repoRoot, sessionID)
		}
		// Provide the live Pi session file as SessionRef so state.TranscriptPath
		// is populated before any mid-turn commits — without it, the post-commit
		// hook can't condense when no shadow branch exists yet.
		return &agent.Event{
			Type:       agent.TurnStart,
			SessionID:  sessionID,
			SessionRef: payload.SessionFile,
			Prompt:     payload.Prompt,
			Timestamp:  now,
		}, nil

	case HookNameAgentEnd:
		if sessionID == "" {
			sessionID = readCachedSessionID(repoRoot)
		}
		sessionRef := captureTranscript(repoRoot, sessionID, payload.SessionFile)
		return &agent.Event{
			Type:       agent.TurnEnd,
			SessionID:  sessionID,
			SessionRef: sessionRef,
			Timestamp:  now,
		}, nil

	case HookNameSessionShutdown:
		clearCachedSessionID(repoRoot)
		return nil, nil //nolint:nilnil // shutdown → cleanup only, no lifecycle event

	default:
		return nil, nil //nolint:nilnil // unknown hooks have no lifecycle action
	}
}

// InstallHooks writes a TypeScript extension that forwards Pi lifecycle events
// to `entire hooks pi <event>`.
func (p *PiAgent) InstallHooks(ctx context.Context, _ bool, force bool) (int, error) {
	root, err := repoRoot(ctx)
	if err != nil {
		return 0, err
	}

	if !force && hooksInstalledAt(root) {
		return 0, nil
	}

	dir := filepath.Join(root, extensionDir)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return 0, fmt.Errorf("create extension dir: %w", err)
	}

	path := filepath.Join(root, extensionFile)
	if err := os.WriteFile(path, []byte(generateExtension()), 0o600); err != nil {
		return 0, fmt.Errorf("write extension: %w", err)
	}

	return 4, nil
}

// UninstallHooks removes the Entire extension directory.
func (p *PiAgent) UninstallHooks(ctx context.Context) error {
	root, err := repoRoot(ctx)
	if err != nil {
		return err
	}
	return os.RemoveAll(filepath.Join(root, extensionDir))
}

// AreHooksInstalled checks whether the Entire extension file exists.
func (p *PiAgent) AreHooksInstalled(ctx context.Context) bool {
	root, err := repoRoot(ctx)
	if err != nil {
		return false
	}
	return hooksInstalledAt(root)
}

func hooksInstalledAt(root string) bool {
	_, err := os.Stat(filepath.Join(root, extensionFile))
	return err == nil
}

func repoRoot(ctx context.Context) (string, error) {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		cwd, gwErr := os.Getwd() //nolint:forbidigo // intentional fallback when WorktreeRoot fails
		if gwErr != nil {
			return "", fmt.Errorf("resolve repo root: %w", errors.Join(err, gwErr))
		}
		return cwd, nil
	}
	return root, nil
}

// repoRootForCtx returns the repo root, falling back to cwd silently. Used by
// hook parsers that should never fail outright if WorktreeRoot fails.
func repoRootForCtx(ctx context.Context) string {
	root, err := repoRoot(ctx)
	if err != nil {
		return ""
	}
	return root
}

func sessionCacheDir(root string) string {
	return filepath.Join(root, ".entire", "tmp")
}

func cacheSessionID(root, id string) {
	if id == "" || root == "" {
		return
	}
	dir := sessionCacheDir(root)
	_ = os.MkdirAll(dir, 0o750)
	_ = os.WriteFile(filepath.Join(dir, activeSessionFile), []byte(id), 0o600)
}

func readCachedSessionID(root string) string {
	if root == "" {
		return ""
	}
	data, err := os.ReadFile(filepath.Join(sessionCacheDir(root), activeSessionFile))
	if err != nil {
		return ""
	}
	return string(data)
}

func clearCachedSessionID(root string) {
	if root == "" {
		return
	}
	_ = os.Remove(filepath.Join(sessionCacheDir(root), activeSessionFile))
}

// captureTranscript copies the Pi JSONL session file to .entire/tmp/<id>.json
// so that Entire can read the transcript. Returns the cached path, or "" on failure.
func captureTranscript(root, sessionID, piSessionFile string) string {
	if root == "" || sessionID == "" || piSessionFile == "" {
		return ""
	}
	dir := sessionCacheDir(root)
	_ = os.MkdirAll(dir, 0o750)
	dst := filepath.Join(dir, sessionID+".json")

	data, err := os.ReadFile(piSessionFile) //nolint:gosec // path from agent hook payload
	if err != nil {
		fmt.Fprintf(os.Stderr, "pi: capture transcript: read %s: %v\n", piSessionFile, err)
		return ""
	}
	if err := os.WriteFile(dst, data, 0o600); err != nil {
		fmt.Fprintf(os.Stderr, "pi: capture transcript: write %s: %v\n", dst, err)
		return ""
	}
	return dst
}

func generateExtension() string {
	return `import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { execFile } from "node:child_process";

export default function (pi: ExtensionAPI) {
  function fireHook(hookName: string, data: Record<string, unknown>): Promise<void> {
    return new Promise((resolve) => {
      try {
        const child = execFile(
          "entire",
          ["hooks", "pi", hookName],
          {
            timeout: 10000,
            windowsHide: true,
          },
          () => resolve(),
        );
        child.stdin?.end(JSON.stringify(data));
      } catch {
        // best effort — don't block the agent
        resolve();
      }
    });
  }

  pi.on("tool_call", async (event) => {
    if (event.toolName !== "bash") {
      return;
    }

    const input = event.input as { command?: string };
    if (typeof input.command !== "string" || input.command.includes("GIT_TERMINAL_PROMPT=")) {
      return;
    }

    // Pi tool subprocesses may inherit a real TTY even though the agent cannot
    // answer hook prompts. Disable git/Entire terminal prompts for bash calls so
    // Entire treats agent-driven commits as non-interactive.
    input.command = "export GIT_TERMINAL_PROMPT=0\n" + input.command;
  });

  pi.on("session_start", async (_event, ctx) => {
    await fireHook("session_start", {
      type: "session_start",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
    });
  });

  pi.on("before_agent_start", async (event, ctx) => {
    await fireHook("before_agent_start", {
      type: "before_agent_start",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
      prompt: event.prompt,
    });
  });

  pi.on("agent_end", async (_event, ctx) => {
    await fireHook("agent_end", {
      type: "agent_end",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
    });
  });

  pi.on("session_shutdown", async () => {
    await fireHook("session_shutdown", {
      type: "session_shutdown",
    });
  });
}
`
}

package pi

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

const (
	compactTranscriptAgent      = "pi"
	compactTranscriptCLIVersion = "unknown"
	compactToolResultSuccess    = "success"
	compactToolResultError      = "error"
)

var compactToolNameMap = map[string]string{
	"edit":  "Edit",
	"read":  "Read",
	"write": "Write",
}

type compactTranscriptLine struct {
	V            int    `json:"v"`
	Agent        string `json:"agent"`
	CLIVersion   string `json:"cli_version"`
	Type         string `json:"type"`
	TS           string `json:"ts,omitempty"`
	ID           string `json:"id,omitempty"`
	InputTokens  int    `json:"input_tokens,omitempty"`
	OutputTokens int    `json:"output_tokens,omitempty"`
	Content      any    `json:"content"`
}

type compactUserTextBlock struct {
	Text string `json:"text"`
}

type compactAssistantTextBlock struct {
	Type string `json:"type"`
	Text string `json:"text"`
}

type compactAssistantToolUseBlock struct {
	Type   string                 `json:"type"`
	ID     string                 `json:"id,omitempty"`
	Name   string                 `json:"name"`
	Input  any                    `json:"input"`
	Result *compactToolResultJSON `json:"result,omitempty"`
}

type compactToolResultJSON struct {
	Output string `json:"output"`
	Status string `json:"status"`
}

// CompactTranscript converts the Pi JSONL transcript at sessionRef into Entire
// Transcript Format and returns the compacted bytes.
func (p *PiAgent) CompactTranscript(_ context.Context, sessionRef string) (*agent.CompactedTranscript, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("read transcript: %w", err)
	}

	compacted, err := compactTranscriptBytes(data)
	if err != nil {
		return nil, err
	}

	return &agent.CompactedTranscript{Transcript: compacted}, nil
}

func compactTranscriptBytes(data []byte) ([]byte, error) {
	active := resolveActiveBranch(data)
	results, err := collectCompactToolResults(data, active)
	if err != nil {
		return nil, err
	}

	cliVersion := compactCLIVersion()
	var buf bytes.Buffer

	scanner := newJSONLScanner(data)
	for scanner.Scan() {
		var entry messageEntry
		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
			continue
		}
		if entry.Type != entryTypeMessage {
			continue
		}
		if active != nil && !active[entry.ID] {
			continue
		}

		switch entry.Message.Role {
		case "user":
			content := compactUserContent(entry.Message.Content)
			if len(content) == 0 {
				continue
			}
			if err := writeCompactTranscriptLine(&buf, compactTranscriptLine{
				V:          1,
				Agent:      compactTranscriptAgent,
				CLIVersion: cliVersion,
				Type:       "user",
				TS:         entry.Timestamp,
				Content:    content,
			}); err != nil {
				return nil, err
			}

		case "assistant":
			content := compactAssistantContent(entry.Message.Content, results)
			if len(content) == 0 {
				continue
			}
			line := compactTranscriptLine{
				V:          1,
				Agent:      compactTranscriptAgent,
				CLIVersion: cliVersion,
				Type:       "assistant",
				TS:         entry.Timestamp,
				ID:         entry.ID,
				Content:    content,
			}
			if entry.Message.Usage != nil {
				line.InputTokens = entry.Message.Usage.Input
				line.OutputTokens = entry.Message.Usage.Output
			}
			if err := writeCompactTranscriptLine(&buf, line); err != nil {
				return nil, err
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("scan transcript: %w", err)
	}
	if buf.Len() == 0 {
		return nil, errors.New("compact transcript produced no output")
	}
	return buf.Bytes(), nil
}

func compactUserContent(raw json.RawMessage) []compactUserTextBlock {
	if text := decodeCompactString(raw); text != "" {
		return []compactUserTextBlock{{Text: text}}
	}

	var items []contentItem
	if err := json.Unmarshal(raw, &items); err != nil {
		return nil
	}

	blocks := make([]compactUserTextBlock, 0, len(items))
	for _, item := range items {
		if item.Type == contentTypeText && item.Text != "" {
			blocks = append(blocks, compactUserTextBlock{Text: item.Text})
		}
	}
	return blocks
}

func compactAssistantContent(raw json.RawMessage, results map[string]compactToolResultJSON) []any {
	if text := decodeCompactString(raw); text != "" {
		return []any{compactAssistantTextBlock{Type: contentTypeText, Text: text}}
	}

	var items []contentItem
	if err := json.Unmarshal(raw, &items); err != nil {
		return nil
	}

	blocks := make([]any, 0, len(items))
	for _, item := range items {
		switch item.Type {
		case contentTypeText:
			if item.Text != "" {
				blocks = append(blocks, compactAssistantTextBlock{
					Type: contentTypeText,
					Text: item.Text,
				})
			}
		case "toolCall":
			block := compactAssistantToolUseBlock{
				Type:  "tool_use",
				ID:    item.ID,
				Name:  normalizeCompactToolName(item.Name),
				Input: decodeCompactInput(item.Arguments),
			}
			if result, ok := results[item.ID]; ok {
				block.Result = &result
			}
			blocks = append(blocks, block)
		}
	}
	return blocks
}

func collectCompactToolResults(data []byte, active map[string]bool) (map[string]compactToolResultJSON, error) {
	results := map[string]compactToolResultJSON{}
	scanner := newJSONLScanner(data)
	for scanner.Scan() {
		var entry messageEntry
		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
			continue
		}
		if entry.Type != entryTypeMessage || entry.Message.Role != "toolResult" {
			continue
		}
		if active != nil && !active[entry.ID] {
			continue
		}
		if entry.Message.ToolCallID == "" {
			continue
		}
		results[entry.Message.ToolCallID] = compactToolResultJSON{
			Output: compactResultOutput(entry.Message.Content),
			Status: compactResultStatus(entry.Message.IsError),
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("scan tool results: %w", err)
	}
	return results, nil
}

func writeCompactTranscriptLine(buf *bytes.Buffer, line compactTranscriptLine) error {
	encoded, err := json.Marshal(line)
	if err != nil {
		return fmt.Errorf("marshal compact transcript line: %w", err)
	}
	if _, err := buf.Write(encoded); err != nil {
		return fmt.Errorf("write compact transcript line: %w", err)
	}
	if err := buf.WriteByte('\n'); err != nil {
		return fmt.Errorf("terminate compact transcript line: %w", err)
	}
	return nil
}

func compactCLIVersion() string {
	if version := strings.TrimSpace(os.Getenv("ENTIRE_CLI_VERSION")); version != "" {
		return version
	}
	return compactTranscriptCLIVersion
}

func normalizeCompactToolName(name string) string {
	if normalized, ok := compactToolNameMap[name]; ok {
		return normalized
	}
	return name
}

func decodeCompactInput(raw json.RawMessage) any {
	if len(raw) == 0 {
		return map[string]any{}
	}

	var decoded any
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return map[string]any{}
	}
	return decoded
}

func decodeCompactString(raw json.RawMessage) string {
	var text string
	if err := json.Unmarshal(raw, &text); err != nil {
		return ""
	}
	return text
}

func compactResultOutput(raw json.RawMessage) string {
	if text := decodeCompactString(raw); text != "" {
		return text
	}

	var items []contentItem
	if err := json.Unmarshal(raw, &items); err == nil {
		texts := make([]string, 0, len(items))
		for _, item := range items {
			if item.Type == contentTypeText && item.Text != "" {
				texts = append(texts, item.Text)
			}
		}
		if len(texts) > 0 {
			return strings.Join(texts, "\n")
		}
	}

	var decoded any
	if err := json.Unmarshal(raw, &decoded); err == nil {
		encoded, err := json.Marshal(decoded)
		if err == nil {
			return string(encoded)
		}
	}
	return string(raw)
}

func compactResultStatus(isError bool) string {
	if isError {
		return compactToolResultError
	}
	return compactToolResultSuccess
}

