		t.Error("expected IsPreview = true")
	}
	dirs := ag.ProtectedDirs()
	if len(dirs) != 1 || dirs[0] != ".pi" {
		t.Errorf("ProtectedDirs = %v, want [.pi]", dirs)
	}
}

func TestPiAgent_InterfaceAssertions(t *testing.T) {
	t.Parallel()
