		t.Error("expected pi to implement PromptExtractor")
	}
	if _, ok := agent.AsTokenCalculator(ag); !ok {
		t.Error("expected pi to implement TokenCalculator")
	}
	if _, ok := agent.AsTranscriptCompactor(ag); !ok {
		t.Error("expected pi to implement TranscriptCompactor")
