	if string(resp.Transcript) != want {
		t.Fatalf("compact transcript = %q, want %q", string(resp.Transcript), want)
	}
}

func TestCompactTranscriptUsesUnknownCLIVersionFallback(t *testing.T) {
	t.Parallel()
	path := writeCompactTranscriptFixture(t, testFlatSessionJSONL)

	resp, err := NewPiAgent().(*PiAgent).CompactTranscript(context.Background(), path)
	if err != nil {
		t.Fatalf("CompactTranscript() error = %v", err)
	}
	if !strings.Contains(string(resp.Transcript), `"cli_version":"unknown"`) {
		t.Fatalf("compact transcript should include unknown cli_version fallback, got %q", string(resp.Transcript))
	}
}

func TestCompactTranscriptFiltersAbandonedBranches(t *testing.T) {
	t.Setenv("ENTIRE_CLI_VERSION", "1.2.3")

