// piHomeEnvVar overrides the default Pi home directory (~/.pi/agent).
// Pi itself reads this variable, so honoring it keeps Entire and Pi in sync
// when a developer points Pi at a non-default home (e.g. for testing).
const piHomeEnvVar = "PI_CODING_AGENT_DIR"

// piSessionDirEnvVar lets tests redirect Pi's session lookup without touching
// the user's real ~/.pi/agent. Mirrors ENTIRE_TEST_<AGENT>_SESSION_DIR used
// by Codex.
const piSessionDirEnvVar = "ENTIRE_TEST_PI_SESSION_DIR"

