// GetSessionDir returns the directory where Pi stores transcripts for this repo.
// Pi sessions live at <piHome>/sessions/<encoded-repo-path>/<timestamp>_<id>.jsonl
// where <encoded-repo-path> replaces '/' with '-' wrapped in '--' delimiters
// (e.g. /Users/foo/repo → --Users-foo-repo--).
//
// Resolution order:
//  1. ENTIRE_TEST_PI_SESSION_DIR (test override; bypasses encoding)
//  2. PI_CODING_AGENT_DIR (Pi's own override; encoding still applies)
//  3. ~/.pi/agent (default)
//
// Pointing this at the native store lets `entire attach <id>` find sessions
// that hooks haven't (yet) captured to .entire/tmp.
func (p *PiAgent) GetSessionDir(repoPath string) (string, error) {
	if override := os.Getenv(piSessionDirEnvVar); override != "" {
		return override, nil
	}
	home, err := resolvePiHome()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, "sessions", encodeRepoPath(repoPath)), nil
}

// GetSessionBaseDir returns the base directory containing per-project session
// subdirectories — used by attach's cross-project fallback when a session was
// started from a different cwd.
func (p *PiAgent) GetSessionBaseDir() (string, error) {
	home, err := resolvePiHome()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, "sessions"), nil
}

// ResolveSessionFile returns the path to the Pi session file for sessionID.
// Pi names files <timestamp>_<sessionID>.jsonl, so glob for the matching ID.
// If the agent passes an absolute path through (e.g. from a hook payload),
// return it unchanged. When no match exists, return a deterministic
// non-existent path so downstream stat checks fail cleanly.
func (p *PiAgent) ResolveSessionFile(sessionDir, sessionID string) string {
	if filepath.IsAbs(sessionID) {
		return sessionID
	}
	if path := findPiSessionByID(sessionDir, sessionID); path != "" {
		return path
	}
	if sessionDir == "" {
		return sessionID
	}
	return filepath.Join(sessionDir, sessionID+".jsonl")
}

// resolvePiHome returns the Pi home directory.
func resolvePiHome() (string, error) {
	if dir := os.Getenv(piHomeEnvVar); dir != "" {
		return dir, nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("resolve user home: %w", err)
	}
	return filepath.Join(home, ".pi", "agent"), nil
}

// encodeRepoPath encodes an absolute repo path into Pi's session-dir scheme:
// '/' → '-', wrapped in '--' delimiters. Empty input returns "".
//
// Examples:
//
//	/Users/foo/repo       → --Users-foo-repo--
//	/Users/foo/repo/      → --Users-foo-repo--   (trailing separator stripped)
func encodeRepoPath(repoPath string) string {
	if repoPath == "" {
		return ""
	}
	cleaned := strings.TrimRight(repoPath, string(filepath.Separator))
	body := strings.ReplaceAll(cleaned, string(filepath.Separator), "-")
	body = strings.TrimPrefix(body, "-")
	return "--" + body + "--"
}

// findPiSessionByID globs sessionDir for a Pi session file matching sessionID.
// Pi's filenames are <timestamp>_<sessionID>.jsonl; if multiple match, the
// lexicographically latest (i.e. most recent timestamp) wins.
func findPiSessionByID(sessionDir, sessionID string) string {
	if sessionDir == "" || sessionID == "" {
		return ""
	}
	matches, err := filepath.Glob(filepath.Join(sessionDir, "*_"+sessionID+".jsonl"))
	if err != nil || len(matches) == 0 {
		return ""
	}
	sort.Strings(matches)
	return matches[len(matches)-1]
}

