+
+	//nolint:gosec // G301: pi reads the directory; standard 0755 permissions
+	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
+		return 0, fmt.Errorf("create extension dir: %w", err)
+	}
+	//nolint:gosec // G306: pi reads the file; standard 0644 permissions
+	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
+		return 0, fmt.Errorf("write extension: %w", err)
+	}
+	return 1, nil
+}
+
+// UninstallHooks removes the entire pi extension directory (if present).
+func (a *PiAgent) UninstallHooks(ctx context.Context) error {
+	path, err := extensionPath(ctx)
+	if err != nil {
+		return err
+	}
+	dir := filepath.Dir(path)
+	if err := os.RemoveAll(dir); err != nil {
+		return fmt.Errorf("remove pi extension dir: %w", err)
+	}
+	return nil
+}
+
+// AreHooksInstalled returns true when the extension file exists and is
+// recognisable as Entire-owned (contains the marker string).
+func (a *PiAgent) AreHooksInstalled(ctx context.Context) bool {
+	path, err := extensionPath(ctx)
+	if err != nil {
+		return false
+	}
+	//nolint:gosec // path from validated repo root
+	data, err := os.ReadFile(path)
+	if err != nil {
+		return false
+	}
+	return strings.Contains(string(data), entireMarker)
+}
diff --git a/cmd/entire/cli/agent/pi/hooks_test.go b/cmd/entire/cli/agent/pi/hooks_test.go
new file mode 100644
index 0000000000..92ca9ea30c
--- /dev/null
+++ b/cmd/entire/cli/agent/pi/hooks_test.go
@@ -0,0 +1,173 @@
+package pi
+
+import (
+	"context"
+	"os"
+	"path/filepath"
+	"strings"
+	"testing"
+)
+
+// Note: t.Parallel is incompatible with t.Chdir.
+
+func TestInstallHooks_FreshInstall(t *testing.T) {
+	dir := t.TempDir()
+	t.Chdir(dir)
+
+	count, err := (&PiAgent{}).InstallHooks(context.Background(), false, false)
+	if err != nil {
+		t.Fatalf("InstallHooks: %v", err)
+	}
+	if count != 1 {
+		t.Errorf("count = %d, want 1", count)
+	}
+
+	path := filepath.Join(dir, ".pi", "extensions", "entire", "index.ts")
+	data, err := os.ReadFile(path)
+	if err != nil {
+		t.Fatalf("extension not written: %v", err)
+	}
+	body := string(data)
+
+	if !strings.Contains(body, `const ENTIRE_CMD = "entire"`) {
+		t.Error("production ENTIRE_CMD missing")
+	}
+	if !strings.Contains(body, "hooks pi ") {
+		t.Error("missing call to `entire hooks pi`")
+	}
+	if !strings.Contains(body, entireMarker) {
+		t.Error("entireMarker missing")
+	}
+	if strings.Contains(body, "go run") {
+		t.Error("production extension should not contain 'go run'")
+	}
+}
+

+//   - session_shutdown    → SessionEnd
+func (a *PiAgent) GetSupportedHooks() []agent.HookType {
+	return []agent.HookType{
+		agent.HookSessionStart,
+		agent.HookSessionEnd,
+		agent.HookUserPromptSubmit,
+		agent.HookStop,
+	}
+}
+
+// piHookPayload is the JSON the embedded TypeScript extension pipes to
+// `entire hooks pi <event>` on stdin.
+type piHookPayload struct {
+	Type        string `json:"type"`
+	Cwd         string `json:"cwd,omitempty"`
+	SessionFile string `json:"session_file,omitempty"`
+	SessionID   string `json:"session_id,omitempty"`
+	Prompt      string `json:"prompt,omitempty"`
+}
+
+// ParseHookEvent translates a Pi hook invocation into a normalised lifecycle
+// event. Implements agent.HookSupport.
+func (a *PiAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
+	data, err := io.ReadAll(stdin)
+	if err != nil {
+		return nil, fmt.Errorf("read pi hook input: %w", err)
+	}
+	if len(data) == 0 {
+		return nil, errors.New("empty pi hook input")
+	}
+
+	var payload piHookPayload
+	if err := json.Unmarshal(data, &payload); err != nil {
+		return nil, fmt.Errorf("parse pi hook payload: %w", err)
+	}
+
+	sessionID := payload.SessionID
+	if sessionID == "" {
+		sessionID = extractSessionIDFromPath(payload.SessionFile)
+	}
+
+	now := time.Now()
+
+	switch hookName {
+	case HookNameSessionStart:
+		cacheSessionID(ctx, sessionID)
+		return &agent.Event{
+			Type:      agent.SessionStart,
+			SessionID: sessionID,
+			Timestamp: now,
+		}, nil
+
+	case HookNameBeforeAgentStart:
+		// Pi emits before_agent_start with a fully-populated session ID, but
+		// we cache it anyway to support the agent_end fallback below.
+		if sessionID == "" {
+			sessionID = readCachedSessionID(ctx)
+		} else {
+			cacheSessionID(ctx, sessionID)
+		}
+		// Provide the live Pi session file as SessionRef so state.TranscriptPath
+		// is populated before any mid-turn commits. Without this, the
+		// post-commit hook cannot condense when no shadow branch exists yet.
+		return &agent.Event{
+			Type:       agent.TurnStart,
+			SessionID:  sessionID,
+			SessionRef: payload.SessionFile,
+			Prompt:     payload.Prompt,
+			Timestamp:  now,
+		}, nil
+
+	case HookNameAgentEnd:
+		if sessionID == "" {
+			sessionID = readCachedSessionID(ctx)
+		}
+		// Capture the Pi JSONL into <repo>/.entire/tmp/pi/<id>.json so the
+		// strategy has a stable transcript reference even if the user later
+		// deletes Pi sessions. The pi/ subdir avoids colliding with paths
+		// other agents (or test harnesses) stage under .entire/tmp/.
+		sessionRef := captureTranscript(ctx, sessionID, payload.SessionFile)
+		return &agent.Event{
+			Type:       agent.TurnEnd,
+			SessionID:  sessionID,
+			SessionRef: sessionRef,
+			Timestamp:  now,
+		}, nil
+
+	case HookNameSessionShutdown:
+		// The TS extension's session_shutdown payload carries no session_id /
+		// session_file, so recover the active session ID from the cache before
+		// clearing it. Without this the SessionEnd event would have empty
+		// SessionID and the strategy couldn't identify which session ended.
+		if sessionID == "" {
+			sessionID = readCachedSessionID(ctx)
+		}
+		clearCachedSessionID(ctx)
+		return &agent.Event{
+			Type:      agent.SessionEnd,
+			SessionID: sessionID,
+			Timestamp: now,
+		}, nil
+
+	default:
+		// Unknown / future hooks have no lifecycle significance.
+		return nil, nil //nolint:nilnil // unknown hook = no lifecycle event (acceptable)
+	}
+}
+
+// --- session ID cache ---
+//
+// Pi's `before_agent_start` event sometimes fires before `session_start` has
+// completed cacheing the session ID (race during early extension load), and
+// `agent_end` may fire after Pi has torn down its session manager. We cache
+// the active session ID at session_start time so subsequent hooks can recover
+// it.
+
+const activeSessionFile = "pi-active-session"
+
+// resolveSessionDir returns the per-repo Pi staging directory.
+// Mirrors GetSessionDir: <repo>/.entire/tmp/pi.
+func resolveSessionDir(ctx context.Context) string {
+	root, err := paths.WorktreeRoot(ctx)
+	if err != nil {
+		//nolint:forbidigo // fallback when no git repo (tests run outside repos)
+		wd, wdErr := os.Getwd()
+		if wdErr != nil {
+			return filepath.Join(paths.EntireTmpDir, piSessionSubdir)
+		}
+		root = wd
+	}
+	return filepath.Join(root, paths.EntireTmpDir, piSessionSubdir)
+}
+
+func cacheSessionID(ctx context.Context, id string) {
+	if id == "" {
+		return
+	}
+	dir := resolveSessionDir(ctx)
+	if err := os.MkdirAll(dir, 0o750); err != nil {
+		logging.Debug(ctx, "pi: cache session id mkdir", slog.String("err", err.Error()))
+		return
+	}
+
+	if err := os.WriteFile(filepath.Join(dir, activeSessionFile), []byte(id), 0o600); err != nil {
+		logging.Debug(ctx, "pi: cache session id write", slog.String("err", err.Error()))
+	}
+}
+
+func readCachedSessionID(ctx context.Context) string {
+	dir := resolveSessionDir(ctx)
+	//nolint:gosec // path constructed from validated repo root
+	data, err := os.ReadFile(filepath.Join(dir, activeSessionFile))
+	if err != nil {
+		return ""
+	}
+	return strings.TrimSpace(string(data))
+}
+
+func clearCachedSessionID(ctx context.Context) {
+	dir := resolveSessionDir(ctx)
+	_ = os.Remove(filepath.Join(dir, activeSessionFile))
+}
+
+// captureTranscript copies the Pi JSONL session file to
+// <repo>/.entire/tmp/pi/<id>.json so Entire has a stable transcript
+// reference. Returns the path to the cached file, or "" if either input is
+// missing. The pi/ namespace under .entire/tmp/ is intentional — see
+// GetSessionDir / piSessionSubdir for the rationale.
+func captureTranscript(ctx context.Context, sessionID, piSessionFile string) string {
+	if sessionID == "" || piSessionFile == "" {
+		return ""
+	}
+	dir := resolveSessionDir(ctx)
+	if err := os.MkdirAll(dir, 0o750); err != nil {
+		logging.Warn(ctx, "pi: capture transcript mkdir failed",
+			slog.String("dir", dir), slog.String("err", err.Error()))
+		return ""
+	}
+	dst := filepath.Join(dir, sessionID+".json")
+	//nolint:gosec // G703: piSessionFile from trusted Pi extension stdin payload
+	data, err := os.ReadFile(piSessionFile)
+	if err != nil {
+		logging.Warn(ctx, "pi: capture transcript read failed",
+			slog.String("src", piSessionFile), slog.String("err", err.Error()))
+		return ""
+	}
+	//nolint:gosec // G703: dst constructed from validated session ID inside .entire/tmp
+	if err := os.WriteFile(dst, data, 0o600); err != nil {
+		logging.Warn(ctx, "pi: capture transcript write failed",
+			slog.String("dst", dst), slog.String("err", err.Error()))
+		return ""
+	}
+	return dst
+}
+
+// extractSessionIDFromPath extracts the UUID from a Pi session filename.
+// Pattern: <timestamp>_<uuid>.jsonl → returns <uuid>
+// Falls back to the basename without extension if the pattern doesn't match.
+func extractSessionIDFromPath(p string) string {
+	if p == "" {
+		return ""
+	}
+	base := filepath.Base(p)
+	base = strings.TrimSuffix(base, ".jsonl")
+	if i := strings.LastIndex(base, "_"); i >= 0 {
+		return base[i+1:]
+	}
+	return base
+}
diff --git a/cmd/entire/cli/agent/pi/lifecycle_test.go b/cmd/entire/cli/agent/pi/lifecycle_test.go
new file mode 100644

+++ b/cmd/entire/cli/agent/pi/pi.go
@@ -0,0 +1,203 @@
+// Package pi implements the Agent interface for the pi coding agent
+// (https://github.com/earendil-works/pi-mono).
+// The npm package the embedded extension imports a type from is
+// `@earendil-works/pi-coding-agent`.
+//
+// This is an in-tree port of the previously-external entire-agent-pi plugin
+// (github.com/entireio/external-agents/agents/entire-agent-pi). The behaviour
+// matches the external version — most notably the active-branch resolution
+// for Pi's tree-shaped sessions — but the integration is plumbed directly
+// through the in-tree Agent / HookSupport / TokenCalculator / TranscriptAnalyzer
+// interfaces rather than the external JSON-over-stdio protocol.
+package pi
+
+import (
+	"context"
+	"errors"
+	"fmt"
+	"log/slog"
+	"os"
+	"path/filepath"
+	"strings"
+
+	"github.com/entireio/cli/cmd/entire/cli/agent"
+	"github.com/entireio/cli/cmd/entire/cli/agent/types"
+	"github.com/entireio/cli/cmd/entire/cli/logging"
+	"github.com/entireio/cli/cmd/entire/cli/paths"
+)
+
+//nolint:gochecknoinits // Agent self-registration is the intended pattern
+func init() {
+	agent.Register(agent.AgentNamePi, NewPiAgent)
+}
+
+// PiAgent implements agent.Agent for the pi coding agent.
+//
+//nolint:revive // PiAgent is clearer than Agent in this context
+type PiAgent struct{}
+
+// NewPiAgent returns a new Pi agent instance.
+func NewPiAgent() agent.Agent {
+	return &PiAgent{}
+}
+
+// --- Identity ---
+
+func (a *PiAgent) Name() types.AgentName    { return agent.AgentNamePi }
+func (a *PiAgent) Type() types.AgentType    { return agent.AgentTypePi }
+func (a *PiAgent) Description() string      { return "Pi coding agent integration for Entire" }
+func (a *PiAgent) IsPreview() bool          { return true }
+func (a *PiAgent) ProtectedDirs() []string  { return []string{".pi"} }
+func (a *PiAgent) ProtectedFiles() []string { return nil }
+
+// DetectPresence reports whether pi is configured for *this repo*. We only
+// check repo-local config (.pi/) and intentionally ignore $PATH — in-tree
+// agents follow the convention used by Claude/Gemini/OpenCode where
+// detection means "this repo is set up for this agent", not "this agent is
+// installed somewhere on this machine". The external plugin uses the broader
+// $PATH check because it can't see repo state; we don't have that limitation.
+func (a *PiAgent) DetectPresence(ctx context.Context) (bool, error) {
+	repoRoot, err := paths.WorktreeRoot(ctx)
+	if err != nil {
+		repoRoot = "."
+	}
+	if _, err := os.Stat(filepath.Join(repoRoot, ".pi")); err == nil {
+		return true, nil
+	}
+	return false, nil
+}
+
+// --- Transcript Storage (chunking) ---
+
+// ReadTranscript reads a captured Pi JSONL session transcript from disk.
+// SessionRef is the absolute path returned by captureTranscript().
+func (a *PiAgent) ReadTranscript(sessionRef string) ([]byte, error) {
+	if sessionRef == "" {
+		return nil, errors.New("empty session ref")
+	}
+	//nolint:gosec // SessionRef from validated lifecycle hook input
+	data, err := os.ReadFile(sessionRef)
+	if err != nil {
+		return nil, fmt.Errorf("read pi transcript %s: %w", sessionRef, err)
+	}
+	return data, nil
+}
+
+// ChunkTranscript splits a Pi JSONL transcript at line boundaries.
+func (a *PiAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
+	chunks, err := agent.ChunkJSONL(content, maxSize)
+	if err != nil {
+		return nil, fmt.Errorf("chunk pi transcript: %w", err)
+	}
+	return chunks, nil
+}
+
+// ReassembleTranscript concatenates JSONL chunks with newlines.
+func (a *PiAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
+	return agent.ReassembleJSONL(chunks), nil
+}
+
+// --- Legacy methods ---
+
+// GetSessionID extracts the session ID from a hook input.
+func (a *PiAgent) GetSessionID(input *agent.HookInput) string {
+	if input == nil {
+		return ""
+	}
+	return input.SessionID
+}
+
+// piSessionSubdir is the per-agent subdirectory under .entire/tmp/ where
+// Pi captures session transcripts. This MUST be agent-specific (not just
+// .entire/tmp) — the framework's AgentForTranscriptPath iterates every
+// agent's session dir to identify the owner of a transcript path, and a
+// broader claim would shadow the .entire/tmp/ paths used by other agents'
+// integration tests and tooling.
+const piSessionSubdir = "pi"
+
+// GetSessionDir returns the directory where Entire stages Pi session
+// transcripts. The Pi extension forwards Pi's native JSONL path on every
+// hook event; on agent_end we copy the file into
+// <repo>/.entire/tmp/pi/<id>.json so condensation can find it
+// deterministically and survive Pi sessions being deleted by the user.
+//
+// When repoPath is empty we resolve the worktree root (so callers running
+// from a subdirectory still get the repo-local staging path) and only fall
+// back to os.Getwd() if no git repo is reachable.
+func (a *PiAgent) GetSessionDir(repoPath string) (string, error) {
+	if repoPath == "" {
+		root, err := paths.WorktreeRoot(context.Background())
+		if err == nil {
+			repoPath = root
+		} else {
+			logging.Debug(context.Background(), "pi: GetSessionDir falling back to cwd",
+				slog.String("err", err.Error()))
+			//nolint:forbidigo // last-resort fallback when no git repo (tests outside repos)
+			wd, wdErr := os.Getwd()
+			if wdErr != nil {
+				return "", fmt.Errorf("resolve repo root or cwd for pi session dir: %w", wdErr)
+			}
+			repoPath = wd
+		}
+	}
+	return filepath.Join(repoPath, paths.EntireTmpDir, piSessionSubdir), nil
+}
+
+// ResolveSessionFile returns the full path to a captured Pi session JSONL
+// file for the given session ID inside sessionDir.
+func (a *PiAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
+	return filepath.Join(sessionDir, agentSessionID+".json")
+}
+
+// ReadSession loads a captured Pi transcript and returns it as an AgentSession.
+func (a *PiAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
+	if input == nil || input.SessionRef == "" {
+		return nil, errors.New("no session ref provided")
+	}
+
+	data, err := os.ReadFile(input.SessionRef)
+	if err != nil {
+		return nil, fmt.Errorf("read pi session: %w", err)
+	}
+	return &agent.AgentSession{
+		AgentName:  a.Name(),
+		SessionID:  input.SessionID,
+		SessionRef: input.SessionRef,
+		NativeData: data,
+	}, nil
+}
+
+// WriteSession writes a captured Pi transcript back to disk so Pi can resume
+// from it. Pi loads sessions from arbitrary paths via `pi --session <path>`,
+// so a plain write is sufficient.
+func (a *PiAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
+	if session == nil {
+		return errors.New("nil session")
+	}
+	if session.SessionRef == "" {
+		return errors.New("session has empty SessionRef")
+	}
+	if len(session.NativeData) == 0 {
+		return errors.New("session has empty NativeData")
+	}
+	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
+		return fmt.Errorf("create pi session dir: %w", err)
+	}
+
+	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
+		return fmt.Errorf("write pi session file: %w", err)
+	}
+	return nil
+}
+
+// FormatResumeCommand returns the shell command to resume a specific Pi
+// session by ID. Pi accepts a partial UUID via `pi --session <id>`. When no
+// session is specified, fall back to `pi --continue` which reopens the most
+// recent session.
+func (a *PiAgent) FormatResumeCommand(sessionID string) string {
+	id := strings.TrimSpace(sessionID)
+	if id == "" {
+		return "pi --continue"
+	}
+	return "pi --session " + id
+}
diff --git a/cmd/entire/cli/agent/pi/pijsonl/pijsonl.go b/cmd/entire/cli/agent/pi/pijsonl/pijsonl.go

+++ b/cmd/entire/cli/agent/pi/transcript.go
@@ -0,0 +1,185 @@
+package pi
+
+import (
+	"encoding/json"
+	"fmt"
+	"os"
+
+	"github.com/entireio/cli/cmd/entire/cli/agent"
+	"github.com/entireio/cli/cmd/entire/cli/agent/pi/pijsonl"
+)
+
+// Compile-time interface assertions
+var (
+	_ agent.TokenCalculator    = (*PiAgent)(nil)
+	_ agent.TranscriptAnalyzer = (*PiAgent)(nil)
+	_ agent.PromptExtractor    = (*PiAgent)(nil)
+)
+
+// CalculateTokenUsage sums per-assistant-message token usage from a Pi JSONL
+// transcript starting at the given line offset. Only assistant messages on
+// the active conversation branch contribute to the totals — see
+// pijsonl.ResolveActiveBranch for the rationale.
+func (a *PiAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
+	usage := &agent.TokenUsage{}
+	if len(transcriptData) == 0 {
+		return usage, nil
+	}
+
+	// IMPORTANT: resolve active branch on FULL data before slicing — a
+	// truncated buffer breaks parentId chains and leaks abandoned branches in.
+	active := pijsonl.ResolveActiveBranch(transcriptData)
+	content := pijsonl.SkipLines(transcriptData, fromOffset)
+
+	scanner := pijsonl.NewScanner(content)
+	for scanner.Scan() {
+		var entry pijsonl.Entry
+		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
+			continue
+		}
+		if entry.Type != pijsonl.EntryTypeMessage || entry.Message.Role != pijsonl.RoleAssistant || entry.Message.Usage == nil {
+			continue
+		}
+		if active != nil && !active[entry.ID] {
+			continue
+		}
+		usage.InputTokens += entry.Message.Usage.Input
+		usage.OutputTokens += entry.Message.Usage.Output
+		usage.CacheReadTokens += entry.Message.Usage.CacheRead
+		usage.CacheCreationTokens += entry.Message.Usage.CacheWrite
+		usage.APICallCount++
+	}
+	if err := scanner.Err(); err != nil {
+		return usage, fmt.Errorf("pi transcript scanner: %w", err)
+	}
+	return usage, nil
+}
+
+// GetTranscriptPosition returns the JSONL line count of the file at path.
+// Used by the strategy as the offset for incremental ExtractModifiedFiles
+// calls. Missing files report 0 (consistent with Claude Code).
+func (a *PiAgent) GetTranscriptPosition(path string) (int, error) {
+	if path == "" {
+		return 0, nil
+	}
+	//nolint:gosec // path from validated SessionRef set by lifecycle hooks
+	data, err := os.ReadFile(path)
+	if err != nil {
+		if os.IsNotExist(err) {
+			return 0, nil
+		}
+		return 0, fmt.Errorf("read pi transcript: %w", err)
+	}
+	return pijsonl.CountLines(data), nil
+}
+
+// ExtractModifiedFilesFromOffset scans Pi assistant tool calls from startOffset
+// onward and returns file paths touched by file-modifying tools (`write`,
+// `edit`). Branch-aware: only counts entries on the active conversation
+// branch.
+func (a *PiAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
+	if path == "" {
+		return nil, 0, nil
+	}
+	//nolint:gosec // path from validated SessionRef
+	data, err := os.ReadFile(path)
+	if err != nil {
+		return nil, 0, fmt.Errorf("read pi transcript: %w", err)
+	}
+
+	totalLines := pijsonl.CountLines(data)
+	active := pijsonl.ResolveActiveBranch(data)
+	content := pijsonl.SkipLines(data, startOffset)
+
+	seen := make(map[string]bool)
+	var files []string
+
+	scanner := pijsonl.NewScanner(content)
+	for scanner.Scan() {
+		var entry pijsonl.Entry
+		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
+			continue
+		}
+		if entry.Type != pijsonl.EntryTypeMessage || entry.Message.Role != pijsonl.RoleAssistant {
+			continue
+		}
+		if active != nil && !active[entry.ID] {
+			continue
+		}
+		var items []pijsonl.ContentItem
+		if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
+			continue
+		}
+		for _, item := range items {
+			if item.Type != "toolCall" {
+				continue
+			}
+			if item.Name != "write" && item.Name != "edit" {
+				continue
+			}
+			var args struct {
+				Path string `json:"path"`
+			}
+			if err := json.Unmarshal(item.Arguments, &args); err != nil {
+				continue
+			}
+			if args.Path != "" && !seen[args.Path] {
+				seen[args.Path] = true
+				files = append(files, args.Path)
+			}
+		}
+	}
+	if err := scanner.Err(); err != nil {
+		return files, totalLines, fmt.Errorf("pi transcript scanner: %w", err)
+	}
+	return files, totalLines, nil
